//! Stage S0 (docs/PLAN.md B5): rcompat against vectors generated by R 4.5.3
//! (validation/R/rcompat_vectors.R, fixtures in tests/fixtures/rcompat/). Every double must match
//! R's bit for bit, NaN payloads included.

use rcompat::arith::{r_pow, round_digits, seq_by, seq_length_out};
use rcompat::format::as_character;
use rcompat::normal::{qnorm, rnorm};
use rcompat::order::order;
use rcompat::rng::RRng;
use rcompat::sample::{sample_int, sample_int_weighted};
use rcompat::summary::{mean, sd, sum, var};
use std::fs;

fn fixture(name: &str) -> Vec<Vec<String>> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../../tests/fixtures/rcompat/").to_string() + name;
    let text = fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    let rows: Vec<Vec<String>> = text
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| l.split('\t').map(str::to_string).collect())
        .collect();
    assert!(!rows.is_empty(), "{path} has no cases");
    rows
}

fn f(s: &str) -> f64 {
    f64::from_bits(u64::from_str_radix(s, 16).unwrap_or_else(|_| panic!("bad hex double {s}")))
}

fn fl(s: &str) -> Vec<f64> {
    if s == "-" {
        Vec::new()
    } else {
        s.split(',').map(f).collect()
    }
}

/// Integers written by R with "%.0f" (some beyond i32).
fn il(s: &str) -> Vec<u64> {
    if s == "-" {
        Vec::new()
    } else {
        s.split(',').map(|v| v.parse().unwrap()).collect()
    }
}

/// Bitwise equality of doubles.
fn same(a: f64, b: f64) -> bool {
    a.to_bits() == b.to_bits()
}

fn assert_same(got: f64, want: f64, what: &str) {
    assert!(same(got, want), "{what}: got {got:e} ({:016x}), R gives {want:e} ({:016x})",
            got.to_bits(), want.to_bits());
}

fn assert_same_vec(got: &[f64], want: &[f64], what: &str) {
    assert_eq!(got.len(), want.len(), "{what}: length");
    for (i, (&g, &w)) in got.iter().zip(want).enumerate() {
        assert_same(g, w, &format!("{what}[{i}]"));
    }
}

fn runif_n(rng: &mut RRng, n: usize) -> Vec<f64> {
    (0..n).map(|_| rng.unif_rand()).collect()
}

#[test]
fn set_seed_state() {
    for row in fixture("random_seed.tsv") {
        let seed: i32 = row[0].parse().unwrap();
        let want: Vec<i32> = row[1].split(',').map(|v| v.parse().unwrap()).collect();
        assert_eq!(RRng::new(seed).random_seed(), want, "set.seed({seed})");
        // and the state loads back as R's GetRNGstate would
        let back = RRng::from_random_seed(&want).unwrap();
        assert_eq!(back.random_seed(), want);
    }
}

#[test]
fn random_seed_checkpoints() {
    for row in fixture("random_seed_after.tsv") {
        let seed: i32 = row[0].parse().unwrap();
        let k: usize = row[1].parse().unwrap();
        let state: Vec<i32> = row[2].split(',').map(|v| v.parse().unwrap()).collect();
        let next = fl(&row[3]);
        let what = format!("set.seed({seed}); runif({k})");
        // exporting: the state after the same draws is R's .Random.seed
        let mut rng = RRng::new(seed);
        runif_n(&mut rng, k);
        assert_eq!(rng.random_seed(), state, "{what}: .Random.seed");
        assert_same_vec(&runif_n(&mut rng, 3), &next, &format!("{what}: continued"));
        // importing: a generator loaded from R's .Random.seed continues R's stream
        let mut loaded = RRng::from_random_seed(&state).unwrap();
        assert_same_vec(&runif_n(&mut loaded, 3), &next, &format!("{what}: loaded"));
    }
}

#[test]
fn runif_streams() {
    for row in fixture("unif.tsv") {
        let seed: i32 = row[0].parse().unwrap();
        let n: usize = row[1].parse().unwrap();
        let mut rng = RRng::new(seed);
        assert_same_vec(&runif_n(&mut rng, n), &fl(&row[2]), &format!("set.seed({seed}); runif({n})"));
    }
}

/// The weight vectors of sample.tsv, rebuilt from their specifications.
fn make_prob(spec: &str, n: usize) -> Option<Vec<f64>> {
    let parts: Vec<&str> = spec.split(':').collect();
    match parts[0] {
        "-" => None,
        "int" => {
            let (a, b, c): (f64, f64, f64) =
                (parts[1].parse().unwrap(), parts[2].parse().unwrap(), parts[3].parse().unwrap());
            // R's %% for these positive doubles is fmod
            Some((1..=n).map(|i| ((i as f64 * a) % b) + c).collect())
        }
        "unif" => Some(runif_n(&mut RRng::new(parts[1].parse().unwrap()), n)),
        "mix" => {
            let k: usize = parts[2].parse().unwrap();
            let mut p = runif_n(&mut RRng::new(parts[1].parse().unwrap()), k);
            p.extend(std::iter::repeat_n(1e-6, n - k));
            Some(p)
        }
        _ => panic!("unknown weight spec {spec}"),
    }
}

#[test]
fn sample_int_against_r() {
    for row in fixture("sample.tsv") {
        let seed: i32 = row[0].parse().unwrap();
        let n: usize = row[1].parse().unwrap();
        let size: usize = row[2].parse().unwrap();
        let replace = row[3] == "1";
        let what = format!("set.seed({seed}); sample.int({n}, {size}, {replace}, prob = {})", row[4]);
        let mut rng = RRng::new(seed);
        let r = match make_prob(&row[4], n) {
            None => sample_int(&mut rng, n, size, replace),
            Some(p) => sample_int_weighted(&mut rng, &p, size, replace),
        }
        .unwrap_or_else(|e| panic!("{what}: {e}"));
        // R's 1-based indices
        let r: Vec<u64> = r.iter().map(|&i| i as u64 + 1).collect();
        let len: usize = row[5].parse().unwrap();
        assert_eq!(r.len(), len, "{what}: length");
        if row[6] == "-" {
            assert_eq!(r, il(&row[7]), "{what}");
        } else {
            let head = il(&row[7]);
            let tail = il(&row[8]);
            assert_eq!(&r[..head.len()], &head[..], "{what}: head");
            assert_eq!(&r[len - tail.len()..], &tail[..], "{what}: tail");
            let ck: u64 = r.iter().enumerate().map(|(i, &v)| (v * (i as u64 + 1)) % 1_000_003).sum();
            assert_eq!(ck.to_string(), row[6], "{what}: checksum");
        }
        assert_same_vec(&runif_n(&mut rng, 3), &fl(&row[9]), &format!("{what}: next uniforms"));
    }
}

#[test]
fn rnorm_against_r() {
    for row in fixture("rnorm.tsv") {
        let seed: i32 = row[0].parse().unwrap();
        let n: usize = row[1].parse().unwrap();
        let (mu, sigma) = (f(&row[2]), f(&row[3]));
        let mut rng = RRng::new(seed);
        let what = format!("set.seed({seed}); rnorm({n}, {mu}, {sigma})");
        assert_same_vec(&rnorm(&mut rng, n, mu, sigma), &fl(&row[4]), &what);
        assert_same_vec(&runif_n(&mut rng, 3), &fl(&row[5]), &format!("{what}: next uniforms"));
    }
}

#[test]
fn qnorm_against_r() {
    for row in fixture("qnorm.tsv") {
        let (p, lower, logp, mu, sigma) = (f(&row[0]), row[1] == "1", row[2] == "1", f(&row[3]), f(&row[4]));
        assert_same(qnorm(p, mu, sigma, lower, logp), f(&row[5]),
                    &format!("qnorm({p:e}, {mu}, {sigma}, lower = {lower}, log = {logp})"));
    }
}

#[test]
fn round_against_r() {
    for row in fixture("round.tsv") {
        let (x, d) = (f(&row[0]), f(&row[1]));
        assert_same(round_digits(x, d), f(&row[2]), &format!("round({x:e}, {d})"));
    }
}

#[test]
fn pow_against_r() {
    for row in fixture("pow.tsv") {
        let (x, y) = (f(&row[0]), f(&row[1]));
        assert_same(r_pow(x, y), f(&row[2]), &format!("{x:e} ^ {y:e}"));
    }
}

#[test]
fn seq_against_r() {
    for row in fixture("seq_by.tsv") {
        let (from, to, by) = (f(&row[0]), f(&row[1]), f(&row[2]));
        let what = format!("seq({from:e}, {to:e}, by = {by:e})");
        match (seq_by(from, to, by), row[3].as_str()) {
            (Err(_), "error") => {}
            (Ok(v), want) if want != "error" => assert_same_vec(&v, &fl(want), &what),
            (got, want) => panic!("{what}: got {got:?}, R gives {want}"),
        }
    }
    for row in fixture("seq_len.tsv") {
        let (from, to, len) = (f(&row[0]), f(&row[1]), f(&row[2]));
        let what = format!("seq({from:e}, {to:e}, length.out = {len})");
        assert_same_vec(&seq_length_out(from, to, len).unwrap(), &fl(&row[3]), &what);
    }
}

#[test]
fn order_against_r() {
    for row in fixture("order.tsv") {
        let decreasing = row[0] == "1";
        let x = fl(&row[1]);
        let want: Vec<usize> = il(&row[2]).into_iter().map(|v| v as usize - 1).collect();
        assert_eq!(order(&x, decreasing), want, "order(n = {}, decreasing = {decreasing})", x.len());
    }
}

#[test]
fn summaries_against_r() {
    for row in fixture("summary.tsv") {
        let x = if let Some(spec) = row[0].strip_prefix("unif:") {
            let p: Vec<&str> = spec.split(':').collect();
            let mut rng = RRng::new(p[0].parse().unwrap());
            let (n, a, b): (usize, f64, f64) = (p[1].parse().unwrap(), f(p[2]), f(p[3]));
            (0..n).map(|_| rng.runif(a, b)).collect()
        } else {
            fl(&row[0])
        };
        let what = |s: &str| format!("{s} of {} values ({})", x.len(), &row[0][..row[0].len().min(40)]);
        let want: Vec<f64> = row[1..9].iter().map(|s| f(s)).collect();
        assert_same(sum(&x, false), want[0], &what("sum"));
        assert_same(mean(&x, false), want[1], &what("mean"));
        assert_same(var(&x, false), want[2], &what("var"));
        assert_same(sd(&x, false), want[3], &what("sd"));
        assert_same(sum(&x, true), want[4], &what("sum(na.rm)"));
        assert_same(mean(&x, true), want[5], &what("mean(na.rm)"));
        assert_same(var(&x, true), want[6], &what("var(na.rm)"));
        assert_same(sd(&x, true), want[7], &what("sd(na.rm)"));
    }
}

#[test]
fn as_character_against_r() {
    let rows = fixture("format.tsv");
    let mut bad = Vec::new();
    for row in &rows {
        let x = f(&row[0]);
        let got = as_character(x);
        if got != row[1] {
            bad.push(format!("{x:e} ({}): got {got:?}, R gives {:?}", row[0], row[1]));
        }
    }
    assert!(bad.is_empty(), "{} of {} differ:\n{}", bad.len(), rows.len(), bad.join("\n"));
}

#[test]
fn strtod_against_r() {
    use rcompat::strtod::as_numeric;
    let rows = fixture("strtod.tsv");
    assert!(rows.len() > 12_000);
    let mut misrounded = 0;
    for row in &rows {
        let (s, want, want_str) = (&row[0], f(&row[1]), &row[2]);
        let got = as_numeric(s);
        assert_same(got, want, &format!("as.numeric({s:?})"));
        assert_eq!(&as_character(got), want_str, "as.character(as.numeric({s:?}))");
        if let Ok(correct) = s.trim().parse::<f64>() {
            if !s.trim().to_ascii_lowercase().contains("inf") && correct.to_bits() != want.to_bits() {
                misrounded += 1;
            }
        }
    }
    // R's parser is not correctly rounded; the fixture holds the cases found (plan B1, M3)
    assert!(misrounded >= 60, "only {misrounded} cases where R differs from correct rounding");
}

/// `set.seed(n); complex(real = runif(n), imaginary = runif(n) - 0.5)`.
fn fft_input(n: usize) -> Vec<rcompat::fft::Complex> {
    let mut rng = RRng::new(n as i32);
    let re = runif_n(&mut rng, n);
    let im: Vec<f64> = runif_n(&mut rng, n).into_iter().map(|u| u - 0.5).collect();
    re.into_iter().zip(im).map(|(r, i)| rcompat::fft::Complex::new(r, i)).collect()
}

#[test]
fn fft_against_r() {
    let rows = fixture("fft.tsv");
    for row in &rows {
        let n: usize = row[0].parse().unwrap();
        let inverse = row[1] == "1";
        let want = fl(&row[2]);
        let got: Vec<f64> = rcompat::fft::fft(&fft_input(n), inverse)
            .unwrap()
            .iter()
            .flat_map(|c| [c.re, c.im])
            .collect();
        assert_same_vec(&got, &want, &format!("fft(n = {n}, inverse = {inverse})"));
    }
    assert!(rows.iter().any(|r| r[0] == "1024") && rows.iter().any(|r| r[0] == "512"));
}

#[test]
fn dnorm_against_r() {
    for row in fixture("dnorm.tsv") {
        let (x, mu, sigma, log) = (f(&row[0]), f(&row[1]), f(&row[2]), row[3] == "1");
        assert_same(rcompat::dnorm(x, mu, sigma, log), f(&row[4]), &format!("dnorm({x}, {mu}, {sigma}, {log})"));
    }
}

#[test]
fn approxfun_against_r() {
    use rcompat::approx::{ApproxFun, Method};
    for (i, row) in fixture("approx.tsv").iter().enumerate() {
        let (x, y, xout) = (fl(&row[0]), fl(&row[1]), fl(&row[2]));
        let method = match row[3].as_str() {
            "linear" => Method::Linear,
            "constant" => Method::Constant { f: f(&row[5]) },
            m => panic!("method {m}"),
        };
        let rule: u8 = row[4].parse().unwrap();
        let fun = ApproxFun::with_rule(&x, &y, method, [rule, rule]).unwrap();
        assert_same_vec(&fun.eval_all(&xout), &fl(&row[6]), &format!("approx case {i}"));
    }
}
